holes=[[
[(453,880),(422,876),(388,849),(336,837),(332,851),(355,906),(370,980),(391,1060),(408,1134),(419,1232),(442,1410),(441,1465),(495,1470),(574,1442),(578,1420),(603,1395),(645,1374),(620,1250),(609,1115),(583,1000),(575,920),(549,861),(525,869),(478,861)]
],[
[(137,692),(201,621),(232,709),(234,742),(206,755)],
[(418,638),(438,670),(464,686),(490,686),(503,679),(501,783),(501,890),(507,974),(525,1009),(535,1135),(547,1260),(551,1357),(544,1380),(516,1399),(505,1320),(497,1230),(496,1170),(486,1120),(485,1070),(475,1020),(480,974),(463,938),(472,909),(450,867),(442,841),(462,822),(469,784),(459,750),(452,727),(448,682)]
]]
for i,poly in enumerate(polys,1):
 im=ImageOps.exif_transpose(Image.open(f'assets/doll-0{i}.jpeg')).convert('RGB'); a=np.array(im);h,w=a.shape[:2]
 p=np.array(poly,dtype=np.float32);p[:,0]*=w/882;p[:,1]*=h/1568;p=p.astype(np.int32)
 inside=np.zeros((h,w),np.uint8);cv2.fillPoly(inside,[p],255)
 for hole in holes[i-1]:
  hp=np.array(hole,dtype=np.float32);hp[:,0]*=w/882;hp[:,1]*=h/1568
  cv2.fillPoly(inside,[hp.astype(np.int32)],0)
 eroded=cv2.erode(inside,np.ones((13,13),np.uint8));dilated=cv2.dilate(inside,np.ones((15,15),np.uint8))
 mask=np.where(inside>0,cv2.GC_PR_FGD,cv2.GC_PR_BGD).astype('uint8');mask[dilated==0]=cv2.GC_BGD;mask[(eroded>0)&((np.ptp(a.astype(np.int16),axis=2)>22)|(a.mean(axis=2)<180))]=cv2.GC_FGD
 cv2.grabCut(a,mask,None,np.zeros((1,65)),np.zeros((1,65)),5,cv2.GC_INIT_WITH_MASK)
 alpha=np.where((mask==1)|(mask==3),255,0).astype('uint8')
 # Preserve enclosed ceramic highlights that share the background's near-white colour.
 count,labels,stats,_=cv2.connectedComponentsWithStats(255-alpha)
 for label in range(1,count):
  x,y,cw,ch,area=stats[label]
  if area<6500 and x>0 and y>0 and x+cw<w and y+ch<h:
   alpha[labels==label]=255
 alpha=cv2.GaussianBlur(alpha,(3,3),.6)
 rgba=Image.fromarray(np.dstack((a,alpha)));rgba=rgba.crop(rgba.getbbox());rgba.thumbnail((950,1300));rgba.save(out/f'doll-0{i}.webp',quality=94)
for i in range(1,21):
 im=Image.open(f'assets/wedding-{i:02}.png').convert('RGB');im.thumbnail((1800,1800));im.save(out/f'wedding-{i:02}.webp',quality=87)
print('Prepared 22 web images.')
